package bw.co.starsign.auth;

import java.util.Set;

/**
 * Which realm roles may be assigned, and by whom.
 * <p>
 * Generated by {@code keycloak/generate_authz.py} from ROLES, PRIVILEGED_ROLES, PRIVILEGED_GRANTOR,
 * ORGANISATION_ROLES and PLATFORM_ROLES; do not edit by hand.
 */
public final class RoleAssignmentRules {

    /** Every application role (realm roles). Nothing else may be assigned. */
    public static final Set<String> ROLES = Set.of("STARSIGN_USER", "ORGANISATION_USER", "SIGNING_OFFICER", "DOCUMENT_MANAGER", "AUDITOR", "ORGANISATION_ADMIN", "PLATFORM_ADMIN", "DEVELOPER");

    /** Only holders of {@link #PRIVILEGED_GRANTOR} may assign these, or manage users who hold them. */
    public static final Set<String> PRIVILEGED_ROLES = Set.of("PLATFORM_ADMIN", "DEVELOPER");

    public static final String PRIVILEGED_GRANTOR = "PLATFORM_ADMIN";

    /** The only roles organisation administrators may assign, within their own organisation. */
    public static final Set<String> ORGANISATION_ROLES = Set.of("ORGANISATION_USER", "SIGNING_OFFICER", "DOCUMENT_MANAGER", "AUDITOR", "ORGANISATION_ADMIN");

    /** Roles without a tenant: their tokens carry no tenant_id and they never see document contents. */
    public static final Set<String> PLATFORM_ROLES = Set.of("PLATFORM_ADMIN");

    /** Base role every organisation user receives. */
    public static final String BASE_ORGANISATION_ROLE = "STARSIGN_USER";

    private RoleAssignmentRules() {
    }
}
